pub fn reply_status_matches(
    reply: &Reply,
    status: WorkStatus,
    state: &WorkState,
    graph: &Graph,
) -> bool {
    match reply {
        Reply::AttemptFailed { attempt } => {
            let Some((index, record)) = state
                .attempts
                .iter()
                .enumerate()
                .find(|(_, record)| &record.id == attempt)
            else {
                return false;
            };
            record.status == AttemptStatus::Failed
                && graph.node(&attempt.node).is_some_and(|node| {
                    let failures = state.attempts[..=index]
                        .iter()
                        .filter(|candidate| {
                            candidate.occurrence() == record.occurrence()
                                && candidate.status == AttemptStatus::Failed
                        })
                        .count();
                    status == status_after_failure(failures, node.max_retries)
                })
        }
        Reply::AttemptSubmitted { attempt, .. } => {
            graph.node(&attempt.node).is_some()
                && (status == success_status_at(graph, &attempt.node, true, false)
                    || status == success_status_at(graph, &attempt.node, true, true))
        }
        Reply::GateApproved { node, .. } => {
            graph.node(node).is_some()
                && (status == success_status_at(graph, node, false, false)
                    || status == success_status_at(graph, node, false, true))
        }
        Reply::Started { .. } | Reply::AttemptBegun { .. } | Reply::AttemptReplaced { .. } => {
            status == WorkStatus::Active
        }
            let reason_text = materialize_summary(reason)?;
            Ok(PreparedCommand::plain(Command::FailAttempt {
                attempt: attempt.clone(),
                reason: reason_text,
            }))
        })
    }

    pub fn replace(
        &self,
        work: &WorkId,
        attempt: &AttemptId,
        reason: &InputValue,
        request_id: Option<String>,
    ) -> Result<Response> {
        let request_id = request_id.unwrap_or_else(|| uuid::Uuid::now_v7().to_string());
        let intent = RequestIntent::ReplaceAttempt {
            work: work.clone(),
            attempt: attempt.clone(),
            reason: reason.clone(),
        };
        self.run_command(work, &intent, request_id, &|loaded, lock| {
            let paths = sheltie_core::work::replacement_input_paths_for(
                &loaded.state,
                &loaded.graph,
                attempt,
            )?;
            let reason = materialize_summary(reason)?;
            sheltie_core::text::Summary::new(&reason, "reason").map_err(|_| {
                Error::Core(sheltie_core::Error::SummaryTooLong {
                    max: sheltie_core::text::Summary::max_bytes(),
                    actual: reason.len(),
                })
            })?;
            let mut observed_inputs = BTreeMap::new();
            for (name, path) in paths {
                let observed = match path {
                    Some(path) => {
                        let file = crate::fsx::open_managed_optional(&self.home, &path)?;
                        file.map(|file| {
                            crate::failpoint::rendezvous("replace_after_input_open", path.as_str())
                                .map_err(|error| Error::io(path.as_str(), error))?;
                            let (sha256, bytes) =
                                file.sha256_bounded(crate::fsx::MAX_FILE_BYTES)?;
                            crate::fsx::verify_managed_file_bound(&self.home, lock, &path, &file)?;
                            Ok::<_, Error>(ObservedFile::new(path, sha256, bytes))
                        })
                        .transpose()?
                    }
                    None => None,
                };
                observed_inputs.insert(name, observed);
            }
            Ok(PreparedCommand::plain(Command::ReplaceAttempt {
                attempt: attempt.clone(),
                reason,
                observed_inputs,
                instruction_text: instruction_text_of(loaded, &attempt.node)?,
            }))
        })
    }

